  // ===========================================================
  // LIBERATION
  // ===========================================================
  void dispose() => _client.close();

  // ============================================================
  // UPLOAD DE FICHIER
  // ============================================================

  // ============================================================
  // UPLOAD DE FICHIER (PDF, images)
  // ============================================================
  Future<Map<String, dynamic>> uploadFile(
    String path,
    PlatformFile? file, {
    String fieldName = 'file',
    Map<String, String>? fields,
  }) async {
    try {
      final uri = Uri.parse('${ApiConstants.apiUrl}$path');
      final request = http.MultipartRequest('POST', uri);

      // Headers d'auth
      final token = _getToken();
      debugPrint('[ApiClient.uploadFile] token: ${token != null ? "${token.substring(0, 20)}..." : "NULL"}');
      if (token != null) {
        request.headers['Authorization'] = 'Bearer $token';
      } else {
        debugPrint('[ApiClient.uploadFile] ATTENTION: token est NULL !');
      }

      // Champs additionnels
      if (fields != null) {
        request.fields.addAll(fields);
      }

      // Fichier
      if (file != null) {
        if (file.bytes != null) {
          request.files.add(http.MultipartFile.fromBytes(
            fieldName,
            file.bytes!,
            filename: file.name,
          ));
        } else if (file.path != null) {
          request.files.add(await http.MultipartFile.fromPath(
            fieldName,
            file.path!,
          ));
        }
      }

      final streamed = await request.send();
      final response = await http.Response.fromStream(streamed);

      if (response.statusCode >= 200 && response.statusCode < 300) {
        return jsonDecode(response.body) as Map<String, dynamic>;
      }

      return {
        'success': false,
        'message': 'Erreur ${response.statusCode} : ${response.body}',
      };
    } catch (e) {
      return {'success': false, 'message': e.toString()};
    }
  }

  // Helper pour recuperer le token
  // ============================================================
  // UPLOAD MULTIPART (news, videos, etc.)
  // ============================================================
  Future<Map<String, dynamic>> postMultipart(
    String path, {
    required Map<String, String> fields,
    required String filePath,
    required String fileField,
  }) async {
    try {
      final uri = Uri.parse('${ApiConstants.apiUrl}$path');
      final request = http.MultipartRequest('POST', uri);

      if (_token != null) {
        request.headers['Authorization'] = 'Bearer $_token';
      }

      request.fields.addAll(fields);

      request.files.add(await http.MultipartFile.fromPath(
        fileField,
        filePath,
      ));

      final streamed = await request.send().timeout(
        const Duration(seconds: ApiConstants.receiveTimeout),
      );
      final response = await http.Response.fromStream(streamed);

      if (response.statusCode >= 200 && response.statusCode < 300) {
        if (response.body.isEmpty) {
          return {'success': true};
        }
        return jsonDecode(response.body) as Map<String, dynamic>;
      }

      _logHttpError(response);
      return {
        'success': false,
        'message': 'Erreur ${response.statusCode} : ${response.body}',
      };
    } catch (e, st) {
      ErrorHandler.log(e, st, 'ApiClient.postMultipart');
      return {'success': false, 'message': e.toString()};
    }
  }

  String? _getToken() {
    return token;
  }
}
